function rng(seed){var a=seed>>>0;return function(){a|=0;a=a+0x6D2B79F5|0;var t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
var FIRST=['Ada','Jo','Mara','Theo','Ivy','Sam'];var LAST=['Higgins','Okafor','Reyes','Kim','Patel','Novak'];
function seedUsers(n,seed){var r=rng(seed||1);var out=[];for(var i=0;i<n;i++)out.push({id:i+1,name:FIRST[Math.floor(r()*FIRST.length)]+' '+LAST[Math.floor(r()*LAST.length)],age:18+Math.floor(r()*50),active:r()>0.3});return out;}
function seedSql(table,rows){return rows.map(function(x){var ks=Object.keys(x);return 'INSERT INTO '+table+' ('+ks.join(', ')+') VALUES ('+ks.map(function(k){return typeof x[k]==='string'?"'"+x[k]+"'":x[k];}).join(', ')+');';}).join('\n');}
